import {CLASSES,EFFECTS,STAT_KEYS} from '../content/classes.js';
import {ITEM_TEMPLATES,ZONES,ENEMIES,treeAt} from '../content/region.js';
export const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}-${Math.random().toString(36).slice(2)}`;
export function createItem(template,owner,extra={}){if(!ITEM_TEMPLATES[template])throw Error('Невідомий предмет');return{id:uid(),template,owner,quality:0,...extra};}
export function createHero(classId,name='Мандрівник',id=uid()){let c=CLASSES[classId];if(!c)throw Error('Невідомий клас');return{id,name,classId,level:1,xp:0,statPoints:5,stats:{...c.stat},hp:1,sp:1,x:15,y:21,facing:1,inventory:[createItem(c.weapon,id),...Array.from({length:6},()=>createItem('potion',id)),...Array.from({length:3},()=>createItem('ether',id))],equipment:{weapon:null,armor:null},effects:[],cooldowns:{},specs:{},dead:false,zeny:80,action:null,actionTime:0,cast:null,path:[],ready:false,online:true,kills:0,deathReason:null,zone:'village'};}
export function makeHero(classId,name,id){let h=createHero(classId,name,id);h.equipment.weapon=h.inventory[0].id;let d=derive(h);h.hp=d.hp;h.sp=d.sp;return h;}
export function derive(h){const s=h.stats,c=CLASSES[h.classId];let bonus={atk:0,matk:0,def:0,mdef:0,hp:0};for(let iid of Object.values(h.equipment||{})){const it=(h.inventory||[]).find(i=>i.id===iid);if(!it)continue;let t=ITEM_TEMPLATES[it.template];for(let[k,v]of Object.entries(t.stats))bonus[k]=(bonus[k]||0)+v*(1+(it.quality||0)*.12);if(it.card){let card=ITEM_TEMPLATES[it.card];for(let[k,v]of Object.entries(card?.stats||{}))bonus[k]=(bonus[k]||0)+v;}}
let ranged=['bow','gun'].includes(c.weapon),magic=['mage','acolyte'].includes(h.classId),might=has(h,'might')?1.2:1;return{hp:130+h.level*19+s.VIT*10+bonus.hp,sp:55+h.level*3+s.INT*4,atk:(14+h.level*3+(ranged?s.DEX*2:s.STR*2)+bonus.atk)*might,matk:(15+h.level*3+s.INT*2.3+bonus.matk)*might,def:(s.VIT*1.1+bonus.def)*(has(h,'exposed')?.75:1),mdef:s.INT+bonus.mdef,hit:85+h.level+s.DEX*1.3,flee:h.level+s.AGI*1.3,crit:Math.min(.3,.025+s.LUK*.0025),range:c.range,interval:c.period/(1+s.AGI*.012+s.DEX*.002),speed:3.7*(has(h,'slow')?.6:1),magic};}
export const has=(h,e)=>h.effects?.some(s=>s.id===e&&s.left>0);
export const hitChance=(hit,flee)=>clamp((85+hit-flee)/100,.15,.97);
export function damage(atk,def,power=1,crit=false){return Math.max(1,Math.round(atk*100/(100+Math.max(0,def))*power*(crit?1.5:1)));}
export function addEffect(target,id,duration,source,potency=0){let def=EFFECTS[id];if(!def||target.boss&&['root','stun'].includes(id))return false;if(id==='stun'){target.cast=null;target.action='hurt';}target.effects??=[];let cur=target.effects.find(e=>e.id===id);if(cur){cur.left=duration||def.duration;cur.stacks=Math.min(def.maxStacks,cur.stacks+1);cur.potency=potency||cur.potency;cur.source=source;if(id==='shield')cur.pool=potency||50;}else target.effects.push({id,left:duration||def.duration,tick:def.tick||0,stacks:1,source,potency,pool:id==='shield'?(potency||50):0});return true;}
export function heal(target,amount){if(target.dead)return 0;let max=target.classId?derive(target).hp:target.maxHp;let val=Math.min(max-target.hp,Math.max(0,amount)*(has(target,'curse')?.5:1));target.hp+=val;return val;}
export function takeDamage(target,amount,{hazard=false,reason='Удар ворога'}={}){if(target.dead)return 0;if(has(target,'evasion')&&!hazard)return 0;if(has(target,'guard'))amount*=.6;let sh=target.effects?.find(e=>e.id==='shield');if(sh){let abs=Math.min(sh.pool,amount);sh.pool-=abs;amount-=abs;if(sh.pool<=0)sh.left=0;}let actual=Math.min(target.hp,Math.max(0,Math.round(amount)));target.hp-=actual;if(target.hp<=0){target.dead=true;target.deathReason=reason;target.path=[];target.cast=null;target.action='death';}return actual;}
export function tickEffects(target,dt){let hits=[];for(let e of target.effects||[]){let active=Math.min(dt,e.left);e.left-=dt;if(e.id==='poison'){e.tick-=active;while(e.tick<=0){let n=takeDamage(target,Math.max(2,e.potency)*e.stacks,{hazard:true,reason:'Отруєння: не використано захист або лікування'});hits.push({source:e.source,damage:n});e.tick+=1;if(target.dead)break;}}}target.effects=(target.effects||[]).filter(e=>e.left>0);return hits;}
export const xpNeeded=level=>65+level*35+Math.floor(level*level*1.5);
export function gainXP(h,amount){h.xp+=amount;let levels=0;while(h.level<85&&h.xp>=xpNeeded(h.level)){h.xp-=xpNeeded(h.level);h.level++;h.statPoints+=5;levels++;}if(h.level===85)h.xp=0;if(levels){let d=derive(h);h.hp=d.hp;h.sp=d.sp;}return levels;}
export function equip(h,itemId){let item=h.inventory.find(i=>i.id===itemId&&i.owner===h.id);if(!item)return false;let t=ITEM_TEMPLATES[item.template];if(!['weapon','armor'].includes(t.kind)||h.level<t.requirements.level||t.requirements.classes&&!t.requirements.classes.includes(h.classId))return false;h.equipment[t.kind]=itemId;h.hp=Math.min(h.hp,derive(h).hp);return true;}
export function compare(h,itemId){let item=h.inventory.find(i=>i.id===itemId);if(!item)return{};let t=ITEM_TEMPLATES[item.template],before=derive(h),copy=structuredClone(h);copy.equipment[t.kind]=itemId;let after=derive(copy);return Object.fromEntries(['atk','matk','def','mdef','hp','sp','interval'].map(k=>[k,after[k]-before[k]]));}
function inside(x,y,r){return x>=r.x&&y>=r.y&&x<r.x+r.w&&y<r.y+r.h;}
export function blocked(zoneId,x,y,flags={}){let z=ZONES[zoneId];if(!z)return true;x=Math.floor(x);y=Math.floor(y);if(x<1||y<1||x>=z.size-1||y>=z.size-1)return true;if(z.kind==='dungeon'&&![...z.roads,...z.floorRooms].some(r=>inside(x,y,r)))return true;if([...z.water,...z.walls,...z.houses].some(r=>inside(x,y,r)))return true;if(zoneId==='crypt'&&!flags.switch&&((x>=20&&x<=29&&y===9)||(x===20&&y>=2&&y<=9)))return true;if(treeAt(zoneId,x,y))return true;return false;}
export function pathfind(zoneId,start,end,flags={}){let z=ZONES[zoneId],sx=Math.floor(start.x),sy=Math.floor(start.y),ex=Math.floor(end.x),ey=Math.floor(end.y);if(blocked(zoneId,ex,ey,flags))return[];let q=[[sx,sy]],head=0,prev=new Map([[`${sx},${sy}`,null]]);while(head<q.length){let [x,y]=q[head++];if(x===ex&&y===ey){let p=[],k=`${x},${y}`;while(prev.get(k)!==null){p.push(k.split(',').map(Number));k=prev.get(k);}return p.reverse();}for(let[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let a=x+dx,b=y+dy,k=`${a},${b}`;if(prev.has(k)||blocked(zoneId,a,b,flags))continue;prev.set(k,`${x},${y}`);q.push([a,b]);}}return[];}
export function lineOfSight(zoneId,a,b,flags={}){let n=Math.ceil(Math.hypot(b.x-a.x,b.y-a.y)*5);for(let i=1;i<n;i++){if(blocked(zoneId,a.x+(b.x-a.x)*i/n,a.y+(b.y-a.y)*i/n,flags))return false;}return true;}
export function move(h,dx,dy,dt,zone,flags){if(h.dead||has(h,'root')||has(h,'stun')||h.cast)return;let len=Math.hypot(dx,dy);if(!len)return;let speed=derive(h).speed,step=Math.min(dt,.1)*speed;let nx=h.x+dx/len*step,ny=h.y+dy/len*step,r=.19;let ok=(x,y)=>[[r,r],[-r,r],[r,-r],[-r,-r]].every(([a,b])=>!blocked(zone,x+a,y+b,flags));if(ok(nx,h.y))h.x=nx;if(ok(h.x,ny))h.y=ny;h.action='walk';h.facing=dx-dy>=0?1:-1;}
export function validateName(s){return typeof s==='string'&&/^[\p{L}\p{N} ’'-]{1,22}$/u.test(s);}
